// NEO fork — the committed thesaurus data still matches its manifest
// (adr-002, source moved to OEWN in adr-003)
//
// The shards are generated by neo-ext/tools/build-oewn.js. This test is the
// guard against a half-regenerated directory or a dropped licence.

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const DIR = path.join(__dirname, '..', 'neo-ext', 'thesaurus', 'en');
const SHARDS = path.join(DIR, 'shards');
const MAX_GZ = 5 * 1024 * 1024;
const { HEADWORD } = require('../neo-ext/lib/word-forms.js');

const manifest = () => JSON.parse(fs.readFileSync(path.join(DIR, 'manifest.json'), 'utf8'));

function shardNames() {
  return fs.readdirSync(SHARDS).filter((f) => f.endsWith('.json.gz')).sort();
}

function readShard(name) {
  return JSON.parse(zlib.gunzipSync(fs.readFileSync(path.join(SHARDS, name))).toString('utf8'));
}

test('manifest: provenance and counts', () => {
  const m = manifest();
  assert.equal(m.format, 3, 'format 3 marks the OEWN source; the shard shape stays 2');
  assert.equal(m.language, 'en');
  assert.equal(m.edition, '2025');
  assert.match(m.sha256, /^[0-9a-f]{64}$/);
  assert.match(m.source, /^https:\/\/github\.com\/globalwordnet\/english-wordnet\//);
  assert.ok(m.headwords > 100000, `headwords ${m.headwords}`);
  assert.ok(m.relations > 500000, `relations ${m.relations}`);
  assert.equal(m.shards, 26);
  assert.ok(m.gzBytes > 0 && m.gzBytes < MAX_GZ, `gzBytes ${m.gzBytes}`);
});

test('shards: one per letter, keys in that letter, counts add up', () => {
  const m = manifest();
  const names = shardNames();
  assert.deepEqual(names, 'abcdefghijklmnopqrstuvwxyz'.split('').map((c) => `${c}.json.gz`));

  let headwords = 0;
  let relations = 0;
  let marked = 0;
  let bytes = 0;
  for (const name of names) {
    const letter = name[0];
    const file = path.join(SHARDS, name);
    bytes += fs.statSync(file).size;
    const entries = readShard(name);
    const keys = Object.keys(entries);
    assert.ok(keys.length > 0, `${name} is empty`);
    for (const key of keys) {
      assert.equal(key[0], letter, `${key} in ${name}`);
      assert.ok(HEADWORD.test(key), `${key} is not a headword the lookup can produce`);
      assert.ok(Array.isArray(entries[key]) && entries[key].length, `${key} has no senses`);
      for (const sense of entries[key]) {
        assert.equal(typeof sense.pos, 'string');
        assert.ok(sense.pos.length > 0);
        assert.ok(Array.isArray(sense.syns) && sense.syns.length, `${key} has an empty sense`);
        for (const syn of sense.syns) {
          relations += 1;
          if (syn.rel) marked += 1;
          assert.equal(typeof syn.w, 'string');
          assert.ok(syn.w.length > 0);
          assert.ok(!/\(/.test(syn.w), `${key}: ${syn.w} still carries a marker`);
          assert.ok(['', 'generic', 'similar', 'related', 'antonym'].includes(syn.rel), `${key}: ${syn.rel}`);
        }
      }
    }
    headwords += keys.length;
  }
  assert.equal(headwords, m.headwords);
  assert.equal(relations, m.relations);
  assert.ok(marked > 1000, `only ${marked} words carry a relation`);
  assert.equal(bytes, m.gzBytes);
});

test('shards: a known word keeps its senses', () => {
  const entries = readShard('b.json.gz');
  const batch = entries.batch;
  assert.ok(Array.isArray(batch) && batch.length >= 2);
  const pos = new Set(batch.map((s) => s.pos));
  assert.ok(pos.has('noun') && pos.has('verb'));
  const all = new Set(batch.flatMap((s) => s.syns.map((x) => x.w)));
  assert.ok(all.size >= 20, `batch has ${all.size} synonyms`);
  assert.ok(all.has('pile') && all.has('group'));
  assert.ok(!all.has('batch'));
  assert.ok(![...all].some((w) => /[()]/.test(w)), 'no relation marker leaks into a word');
});

test('relations: a known opposite is labelled, not glued to the word', () => {
  const entries = readShard('g.json.gz');
  const good = entries.good;
  assert.ok(Array.isArray(good));
  const antonyms = good.flatMap((s) => s.syns.filter((x) => x.rel === 'antonym').map((x) => x.w));
  assert.ok(antonyms.includes('bad'), `good antonyms: ${antonyms.slice(0, 5)}`);
  assert.ok(!antonyms.some((w) => w.includes('(')));
});

test('both licences ship beside the data', () => {
  const cc = fs.readFileSync(path.join(DIR, 'LICENSE.md'), 'utf8');
  assert.match(cc, /Creative Commons Attribution 4\.0/);
  assert.match(cc, /Princeton/);
  assert.match(cc, /Open English Wordnet/i);
  const wn = fs.readFileSync(path.join(DIR, 'WNDB_License.txt'), 'utf8');
  assert.match(wn, /Princeton/);
  assert.match(wn, /Permission to use, copy, modify and distribute/);
});
